// localStorage implementation of the chat API contract. It follows the backend's
// rules (turn counting, latest-pair-only edits, closed sessions, cursors) so the UI
// can be swapped to HTTP without changing screens. Replies imitate the backend's
// StubChatAiClient; they are not generated by AI.
import { characterName } from './characters';
import {
  ChatApiError, REQUIRED_TURNS,
  type ChatApi, type ChatMessage, type ChatSession, type SessionListItem,
} from './types';

const storageKey = 'mowoo.chat.v1';
interface Store { sessions: ChatSession[]; messages: Record<string, ChatMessage[]> }

// Two finished sample chats so the archive isn't empty on first visit.
// They live only in this mock and disappear once the real API replaces it.
function sampleStore(): Store {
  const store: Store = { sessions: [], messages: {} };
  const samples = [
    { id: 'sample-0000-4000-8000-000000000001', at: '2026-11-06T11:00:00.000Z', lines: ['내일 면접인데 너무 떨려.', '다른 지원자들이 다 나보다 잘할 것 같아.'] },
    { id: 'sample-0000-4000-8000-000000000002', at: '2026-11-10T12:30:00.000Z', lines: ['오늘 퇴근길에 타코야키 트럭을 만났어.', '별거 아닌데 기분이 좋아졌어.'] },
  ];
  samples.forEach(({ id, at, lines }) => {
    const messages: ChatMessage[] = [];
    lines.forEach((content, i) => {
      const base = { createdAt: at, editedAt: null, diaryReferences: [] };
      messages.push({ ...base, id: `${id}-u${i}`, sequenceNo: i * 2 + 1, senderRole: 'USER', characterId: null, content });
      messages.push({ ...base, id: `${id}-a${i}`, sequenceNo: i * 2 + 2, senderRole: 'ASSISTANT', characterId: 'local-mowoo-kind', content: stubReply('local-mowoo-kind') });
    });
    store.messages[id] = messages;
    store.sessions.push(withProgress({ id, characterId: 'local-mowoo-kind', title: null, summary: null, startedAt: at, endedAt: at, completedTurns: 0, canGenerateDiary: false }, messages));
  });
  return store;
}

function load(): Store {
  try {
    const raw = localStorage.getItem(storageKey);
    if (raw) return JSON.parse(raw) as Store;
  } catch { /* fall through to the sample store */ }
  return sampleStore();
}
function save(store: Store) {
  try { localStorage.setItem(storageKey, JSON.stringify(store)); } catch { /* storage full or blocked */ }
}

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const uuid = () => crypto.randomUUID();
const now = () => new Date().toISOString();

function countTurns(messages: ChatMessage[]) {
  let turns = 0;
  for (let i = 0; i + 1 < messages.length; i++) {
    if (messages[i].senderRole === 'USER' && messages[i + 1].senderRole === 'ASSISTANT') { turns++; i++; }
  }
  return turns;
}
function withProgress(session: ChatSession, messages: ChatMessage[]): ChatSession {
  const completedTurns = countTurns(messages);
  return { ...session, completedTurns, canGenerateDiary: completedTurns >= REQUIRED_TURNS };
}
function findSession(store: Store, id: string) {
  const session = store.sessions.find(s => s.id === id);
  if (!session) throw new ChatApiError('SESSION_NOT_FOUND', 404, '대화를 찾을 수 없어요.');
  return session;
}
function requireOpen(session: ChatSession) {
  if (session.endedAt) throw new ChatApiError('SESSION_CLOSED', 409, '이미 종료된 대화예요.');
}
function requireContent(content: string) {
  const trimmed = content.trim();
  if (!trimmed) throw new ChatApiError('MESSAGE_EMPTY', 400, '메시지를 입력해 주세요.');
  return trimmed;
}
function stubReply(characterId: string) {
  return `${characterName(characterId)}가 듣고 있어요. 조금 더 이야기해 줄래요?`;
}
function page<T>(items: T[], limit = 20, cursor?: string | null) {
  const size = Math.min(100, Math.max(1, limit));
  const start = cursor ? Number(cursor) : 0;
  const slice = items.slice(start, start + size);
  const next = start + size < items.length ? String(start + size) : null;
  return { slice, next };
}

export const mockChatApi: ChatApi = {
  async createSession({ characterId }) {
    await delay(150);
    const store = load();
    const session: ChatSession = {
      id: uuid(), characterId, title: null, summary: null,
      startedAt: now(), endedAt: null, completedTurns: 0, canGenerateDiary: false,
    };
    store.sessions.push(session);
    store.messages[session.id] = [];
    save(store);
    return session;
  },

  async listSessions({ limit, cursor } = {}) {
    await delay(150);
    const store = load();
    const newest = [...store.sessions]
      .filter(s => (store.messages[s.id] ?? []).length > 0)
      .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
    const { slice, next } = page(newest, limit, cursor);
    const items: SessionListItem[] = slice.map(s => ({
      ...s,
      preview: store.messages[s.id]?.find(m => m.senderRole === 'USER')?.content ?? null,
    }));
    return { items, nextCursor: next };
  },

  async getSession(sessionId, { limit, cursor } = {}) {
    await delay(150);
    const store = load();
    const session = findSession(store, sessionId);
    // Newest page first; ascending sequenceNo inside a page, like the backend.
    const newestFirst = [...(store.messages[sessionId] ?? [])].reverse();
    const { slice, next } = page(newestFirst, limit, cursor);
    return { session, messages: { items: slice.reverse(), nextCursor: next } };
  },

  async endSession(sessionId) {
    await delay(150);
    const store = load();
    const session = findSession(store, sessionId);
    requireOpen(session);
    session.endedAt = now();
    save(store);
    return session;
  },

  async deleteSession(sessionId) {
    await delay(150);
    const store = load();
    findSession(store, sessionId);
    store.sessions = store.sessions.filter(s => s.id !== sessionId);
    delete store.messages[sessionId];
    save(store);
  },

  async sendMessage(sessionId, { content }) {
    const text = requireContent(content);
    await delay(700);
    const store = load();
    const session = findSession(store, sessionId);
    requireOpen(session);
    const messages = store.messages[sessionId] ?? (store.messages[sessionId] = []);
    const nextSeq = (messages.at(-1)?.sequenceNo ?? 0) + 1;
    const userMessage: ChatMessage = {
      id: uuid(), sequenceNo: nextSeq, senderRole: 'USER', characterId: null,
      content: text, createdAt: now(), editedAt: null, diaryReferences: [],
    };
    const assistantMessage: ChatMessage = {
      id: uuid(), sequenceNo: nextSeq + 1, senderRole: 'ASSISTANT', characterId: session.characterId,
      content: stubReply(session.characterId), createdAt: now(), editedAt: null, diaryReferences: [],
    };
    messages.push(userMessage, assistantMessage);
    Object.assign(session, withProgress(session, messages));
    save(store);
    return { userMessage, assistantMessage, completedTurns: session.completedTurns, canGenerateDiary: session.canGenerateDiary };
  },

  async editMessage(sessionId, messageId, { content }) {
    const text = requireContent(content);
    await delay(700);
    const store = load();
    const session = findSession(store, sessionId);
    requireOpen(session);
    const messages = store.messages[sessionId] ?? [];
    const index = messages.findIndex(m => m.id === messageId);
    if (index < 0) throw new ChatApiError('MESSAGE_NOT_FOUND', 404, '메시지를 찾을 수 없어요.');
    const isLatestPair = index === messages.length - 2 && messages[index].senderRole === 'USER' && messages[index + 1].senderRole === 'ASSISTANT';
    if (!isLatestPair) throw new ChatApiError('MESSAGE_NOT_EDITABLE', 409, '가장 최근 메시지만 수정할 수 있어요.');
    const edited = now();
    const userMessage = { ...messages[index], content: text, editedAt: edited };
    const assistantMessage = { ...messages[index + 1], content: stubReply(session.characterId), editedAt: edited };
    messages.splice(index, 2, userMessage, assistantMessage);
    save(store);
    return { userMessage, assistantMessage };
  },
};
